//! The TypeObjects and TypeInformation that Cyclone DDS's IDL compiler
//! writes (tests/fixtures/cyclonedds, regenerated by its update.sh):
//! rustorb-xtypes reads them, writes them back to the same octets, and
//! computes the same hashes.

use std::path::{Path, PathBuf};

use rustorb_cdr::{ByteOrder, Decoder, Encoding};
use std::sync::Arc;

use rustorb_xtypes::type_object::*;
use rustorb_xtypes::types::*;
use rustorb_xtypes::xcdr2::{self, Xcdr2};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/cyclonedds")
}

fn read_hex(path: &Path) -> Vec<u8> {
    let text = std::fs::read_to_string(path).unwrap();
    let hex: String = text.split_whitespace().collect();
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

/// idlc's type mapping: minimal pairs, complete pairs, and
/// complete-to-minimal identifier pairs.
struct TypeMap {
    minimal: Vec<TypeIdentifierTypeObjectPair>,
    complete: Vec<TypeIdentifierTypeObjectPair>,
    complete_to_minimal: Vec<TypeIdentifierPair>,
}

fn type_map(name: &str) -> (TypeInformation, TypeMap, Vec<u8>, Vec<u8>) {
    let info_bytes = read_hex(&fixtures().join(format!("{name}.typeinfo")));
    let map_bytes = read_hex(&fixtures().join(format!("{name}.typemap")));
    let info = TypeInformation::from_bytes(&info_bytes, ByteOrder::Little).unwrap();
    let mut dec = Decoder::new(&map_bytes, ByteOrder::Little, Encoding::Xcdr2);
    let map = TypeMap {
        minimal: Xcdr2::decode(&mut dec).unwrap(),
        complete: Xcdr2::decode(&mut dec).unwrap(),
        complete_to_minimal: Xcdr2::decode(&mut dec).unwrap(),
    };
    assert!(dec.is_empty(), "{name}: octets after the type map");
    (info, map, info_bytes, map_bytes)
}

fn names() -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(fixtures())
        .unwrap()
        .filter_map(|e| {
            let p = e.unwrap().path();
            (p.extension()? == "typeinfo").then(|| p.file_stem()?.to_str().map(String::from))?
        })
        .collect();
    names.sort();
    names
}

#[test]
fn round_trip_and_hashes() {
    let names = names();
    assert!(names.len() >= 10, "{names:?}");
    for name in names {
        let (info, map, info_bytes, map_bytes) = type_map(&name);
        // Written back, octet for octet.
        assert_eq!(
            xcdr2::to_bytes(&info, ByteOrder::Little).unwrap(),
            info_bytes,
            "{name}: TypeInformation"
        );
        let mut enc = rustorb_cdr::Encoder::new(ByteOrder::Little, Encoding::Xcdr2);
        map.minimal.encode(&mut enc).unwrap();
        map.complete.encode(&mut enc).unwrap();
        map.complete_to_minimal.encode(&mut enc).unwrap();
        assert_eq!(enc.into_bytes(), map_bytes, "{name}: type map");
        // Each TypeObject hashes to its TypeIdentifier, and has the size
        // the TypeInformation gives.
        for pair in map.minimal.iter().chain(&map.complete) {
            assert_eq!(
                pair.type_object.type_identifier().unwrap(),
                pair.type_identifier,
                "{name}: {:?}",
                pair.type_object
            );
        }
        for (with_deps, pairs) in [
            (&info.minimal, &map.minimal),
            (&info.complete, &map.complete),
        ] {
            let all =
                std::iter::once(&with_deps.typeid_with_size).chain(&with_deps.dependent_typeids);
            for t in all {
                let pair = pairs
                    .iter()
                    .find(|p| p.type_identifier == t.type_id)
                    .unwrap_or_else(|| panic!("{name}: {:?} not in the map", t.type_id));
                assert_eq!(
                    pair.type_object.to_bytes().unwrap().len() as u32,
                    t.typeobject_serialized_size,
                    "{name}"
                );
            }
        }
    }
}

// ---------- The same types, described by hand ---------------------------

fn p(p: Primitive) -> Type {
    Type::Primitive(p)
}

fn bounded(bound: u32) -> Type {
    Type::String { wide: false, bound }
}

fn member(name: &str, id: u32, ty: Type) -> StructMember {
    StructMember::new(name, id, ty)
}

fn key(name: &str, id: u32, ty: Type) -> StructMember {
    StructMember {
        key: true,
        ..StructMember::new(name, id, ty)
    }
}

fn final_struct(name: &str, members: Vec<StructMember>) -> Type {
    StructType {
        name: name.into(),
        extensibility: Extensibility::Final,
        members,
        ..StructType::default()
    }
    .into()
}

fn greeting() -> Type {
    final_struct(
        "HelloWorld::Greeting",
        vec![
            member("index", 0, p(Primitive::Uint32)),
            member("message", 1, Type::string()),
        ],
    )
}

fn shape() -> Type {
    final_struct(
        "Keyed::Shape",
        vec![
            key("id", 0, p(Primitive::Uint32)),
            member("index", 1, p(Primitive::Uint32)),
            member("message", 2, Type::string()),
        ],
    )
}

/// The types of Fixtures.idl, by name.
struct Fx {
    color: Type,
    perm: Type,
    long_seq10: Type,
    name: Type,
    matrix: Type,
    plain: Type,
    inner: Type,
    mutable: Type,
    u: Type,
    ue: Type,
    hashed: Type,
    nested: Type,
    derived: Type,
    all: Type,
    top: Type,
}

fn fx() -> Fx {
    use Primitive::*;
    let color: Type = EnumType {
        name: "Fx::Color".into(),
        literals: [("RED", 0), ("GREEN", 1), ("BLUE", 7)]
            .into_iter()
            .map(|(name, value)| EnumLiteral {
                name: name.into(),
                value,
                default: false,
            })
            .collect(),
        ..EnumType::default()
    }
    .into();
    let perm: Type = BitmaskType {
        name: "Fx::Perm".into(),
        bit_bound: 8,
        flags: [("READ", 0), ("WRITE", 1), ("EXEC", 5)]
            .into_iter()
            .map(|(name, position)| Bitflag {
                name: name.into(),
                position,
            })
            .collect(),
        ..BitmaskType::default()
    }
    .into();
    let long_seq10: Type = AliasType {
        name: "Fx::LongSeq10".into(),
        related: Type::Sequence(Arc::new(SequenceType {
            element: Element::new(p(Int32)),
            bound: 10,
        })),
    }
    .into();
    let name: Type = AliasType {
        name: "Fx::Name".into(),
        related: bounded(20),
    }
    .into();
    let matrix: Type = AliasType {
        name: "Fx::Matrix".into(),
        related: Type::Array(Arc::new(ArrayType {
            element: Element::new(p(Int32)),
            dimensions: vec![2, 3],
        })),
    }
    .into();
    let plain = final_struct(
        "Fx::Plain",
        [
            ("b", Boolean),
            ("o", Byte),
            ("s", Int16),
            ("us", Uint16),
            ("l", Int32),
            ("ul", Uint32),
            ("ll", Int64),
            ("ull", Uint64),
            ("f", Float32),
            ("d", Float64),
            ("c", Char8),
            // idlc 0.10.4 gives int8 and uint8 the TypeIdentifiers of char
            // and octet, not TK_INT8 and TK_UINT8 of DDS-XTypes 1.3.
            ("i8", Char8),
            ("u8", Byte),
        ]
        .into_iter()
        .enumerate()
        .map(|(i, (n, t))| member(n, i as u32, p(t)))
        .collect(),
    );
    let inner: Type = StructType {
        name: "Fx::Inner".into(),
        extensibility: Extensibility::Appendable,
        members: vec![key("id", 0, p(Int32)), member("big", 1, bounded(300))],
        ..StructType::default()
    }
    .into();
    let mutable: Type = StructType {
        name: "Fx::Mut".into(),
        extensibility: Extensibility::Mutable,
        members: vec![
            member("a", 5, p(Int32)),
            StructMember {
                optional: true,
                ..member("b", 2, Type::string())
            },
            key("k", 9, p(Int16)),
            member("inner", 10, inner.clone()),
        ],
        ..StructType::default()
    }
    .into();
    let u: Type = UnionType {
        name: "Fx::U".into(),
        extensibility: Extensibility::Final,
        discriminator: p(Int32),
        members: vec![
            UnionMember::new("x", 0, p(Int32), vec![2, 1]),
            UnionMember::new("s", 1, Type::string(), vec![3]),
            UnionMember {
                default: true,
                ..UnionMember::new("i", 2, inner.clone(), vec![])
            },
        ],
        ..UnionType::default()
    }
    .into();
    let ue: Type = UnionType {
        name: "Fx::UE".into(),
        extensibility: Extensibility::Appendable,
        discriminator: color.clone(),
        members: vec![
            UnionMember::new("r", 0, p(Float64), vec![0]),
            UnionMember::new("n", 1, name.clone(), vec![7]),
        ],
        ..UnionType::default()
    }
    .into();
    let hashid = |name: &str, hash_id: Option<&str>, ty: Type| StructMember {
        annotations: AppliedBuiltinMemberAnnotations {
            hash_id: hash_id.map(String::from),
            ..Default::default()
        },
        ..member(
            name,
            rustorb_typesupport::hashed_member_id(match hash_id {
                Some(h) if !h.is_empty() => h,
                _ => name,
            }),
            ty,
        )
    };
    let hashed: Type = StructType {
        name: "Fx::Hashed".into(),
        extensibility: Extensibility::Mutable,
        autoid_hash: true,
        members: vec![
            hashid("alpha", None, p(Int32)),
            hashid("beta", Some(""), Type::string()),
            hashid("gamma", Some("other"), p(Int32)),
        ],
        ..StructType::default()
    }
    .into();
    let nested: Type = StructType {
        name: "Fx::Nested".into(),
        extensibility: Extensibility::Final,
        nested: true,
        members: vec![member("v", 0, p(Int32))],
        ..StructType::default()
    }
    .into();
    let derived: Type = StructType {
        name: "Fx::Derived".into(),
        extensibility: Extensibility::Final,
        base: Some(nested.clone()),
        members: vec![member("w", 1, p(Int32))],
        ..StructType::default()
    }
    .into();
    let seq = |ty: Type, bound: u32| {
        Type::Sequence(Arc::new(SequenceType {
            element: Element::new(ty),
            bound,
        }))
    };
    let array = |ty: Type, dimensions: Vec<u32>| {
        Type::Array(Arc::new(ArrayType {
            element: Element::new(ty),
            dimensions,
        }))
    };
    let all = final_struct(
        "Fx::All",
        vec![
            member("color", 0, color.clone()),
            member("perm", 1, perm.clone()),
            member("ls", 2, long_seq10.clone()),
            member("name", 3, name.clone()),
            member("m", 4, matrix.clone()),
            member("inners", 5, seq(inner.clone(), 0)),
            member("ss", 6, seq(seq(p(Int32), 0), 0)),
            member("arr", 7, array(inner.clone(), vec![4])),
            member("big_arr", 8, array(p(Int32), vec![300])),
            member("strs", 9, seq(Type::string(), 500)),
            member("u", 10, u.clone()),
            member("ue", 11, ue.clone()),
            member("mut", 12, mutable.clone()),
            member("h", 13, hashed.clone()),
            member("der", 14, derived.clone()),
            member("p", 15, plain.clone()),
            StructMember {
                external: true,
                ..member("ext", 16, inner.clone())
            },
            StructMember {
                optional: true,
                ..member("opt", 17, p(Int32))
            },
        ],
    );
    let top = final_struct(
        "Fx::Top",
        vec![key("id", 0, p(Int32)), member("all", 1, all.clone())],
    );
    Fx {
        color,
        perm,
        long_seq10,
        name,
        matrix,
        plain,
        inner,
        mutable,
        u,
        ue,
        hashed,
        nested,
        derived,
        all,
        top,
    }
}

#[test]
fn built_like_cyclonedds() {
    let fx = fx();
    let _ = (
        &fx.color,
        &fx.perm,
        &fx.long_seq10,
        &fx.name,
        &fx.matrix,
        &fx.nested,
    );
    let cases = [
        ("HelloWorld_Greeting", greeting()),
        ("Keyed_Shape", shape()),
        ("Fx_Plain", fx.plain),
        ("Fx_Inner", fx.inner),
        ("Fx_Mut", fx.mutable),
        ("Fx_U", fx.u),
        ("Fx_UE", fx.ue),
        ("Fx_Hashed", fx.hashed),
        ("Fx_Derived", fx.derived),
        ("Fx_All", fx.all),
        ("Fx_Top", fx.top),
    ];
    assert_eq!(cases.len(), names().len());
    for (name, ty) in cases {
        let (info, map, info_bytes, _) = type_map(name);
        let built = TypeObjects::new(&ty).unwrap();
        // The same TypeObjects, in the same order.
        for (ours, theirs) in [
            (&built.minimal, &map.minimal),
            (&built.complete, &map.complete),
        ] {
            assert_eq!(ours.len(), theirs.len(), "{name}");
            for (o, t) in ours.iter().zip(theirs.iter()) {
                assert_eq!(o, t, "{name}");
            }
        }
        assert_eq!(built.information, info, "{name}");
        assert_eq!(
            built
                .information
                .to_bytes(rustorb_cdr::ByteOrder::Little)
                .unwrap(),
            info_bytes,
            "{name}"
        );
    }
}

/// What the fuzz target does, on every one-octet change of the fixtures:
/// no panic, and what decodes encodes stably.
#[test]
fn mutated_type_objects() {
    for name in names() {
        let (_, map, _, _) = type_map(&name);
        for pair in map.minimal.iter().chain(&map.complete) {
            let bytes = pair.type_object.to_bytes().unwrap();
            for at in 0..bytes.len() {
                for value in [0x00, 0x01, 0x7f, 0x80, 0xff] {
                    let mut mutated = bytes.clone();
                    mutated[at] = value;
                    if let Ok(o1) = TypeObject::from_bytes(&mutated) {
                        let b2 = o1.to_bytes().unwrap();
                        let o2 = TypeObject::from_bytes(&b2).unwrap();
                        assert_eq!(o2.to_bytes().unwrap(), b2, "{name} at {at}");
                    }
                }
            }
        }
    }
}
